(7744011, 1277632, 147314, '<td valign="top">Congrats on the blue and your first FS win. Great picture.</td>', 'Congrats on the blue and your first FS win. Great picture.', '2023-05-08 03:29:38.000000', NULL, 0),
(7744013, 1277531, 163081, '<td valign="top">The graffiti is a riot of colors and shapes, with bold lines and intricate designs that seem to leap off the walls. Some of the images are abstract, while others depict recognizable objects or scenes. As she approaches the end of the alley, she pauses for a moment to look back at the kaleidoscope of images that she''s just passed through. This image is 1 out of a million. A keeper for sure and should have scored much higher. IMHO one a your better ones. Congratulations on the ribbon. I give you my Blue dragon award for this one. <a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1173261" rel="nofollow" target="_blank"><img border="0" src="https://images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173261.jpg" xalt="'' . substr(''https://images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173261.jpg'', strrpos(''https://images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173261.jpg'', ''/'') + 1) . ''"/></a></td>', 'The graffiti is a riot of colors and shapes, with bold lines and intricate designs that seem to leap off the walls. Some of the images are abstract, while others depict recognizable objects or scenes. As she approaches the end of the alley, she pauses for a moment to look back at the kaleidoscope of images that she''s just passed through. This image is 1 out of a million. A keeper for sure and should have scored much higher. IMHO one a your better ones. Congratulations on the ribbon. I give you my Blue dragon award for this one. ', '2023-05-08 05:43:37.000000', NULL, 0),
(7744014, 1277774, 2158, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by glad2badad:</b></div><hr/><i> Lovely shade of orange!  Umm ... couldn''t you figure out a way to exclude that pole on the right?  :-} </i></td></tr></table> <br/> <br/>The photo was taken while my car was stopped at a red light so I couldn''t change the composition. I contemplated cropping out the light, but somehow the photo felt incomplete without it.</td>', 'Originally posted by glad2badad: Lovely shade of orange!  Umm ... couldn''t you figure out a way to exclude that pole on the right?  :-}   The photo was taken while my car was stopped at a red light so I couldn''t change the composition. I contemplated cropping out the light, but somehow the photo felt incomplete without it.', '2023-05-08 05:59:27.000000', NULL, 0),
